const note=(w,topic)=>({
  goal:`Chốt lại tuần ${w}: ghi lại những gì đã học về ${topic} và lưu vào Git.`,
  time:"45–60 phút",
  learn:["Cách viết learning note ngắn: Đã học gì · Làm được gì · Vướng gì · Tuần sau làm gì","Conventional Commits (feat:, docs:, test:, chore:)"],
  ai:[["Claude.ai / ChatGPT","Biên tập note cho gọn",`Đây là ghi chú thô tuần ${w} của tôi về ${topic}. Hãy sắp xếp thành learning note gồm 4 mục: Đã học, Đã làm, Còn vướng, Tuần sau. Giữ nguyên ý của tôi, không bịa thêm:\n\n<dán ghi chú>`]],
  res:[["Conventional Commits","https://www.conventionalcommits.org/"],R.git],
  practice:[`Tạo file docs/learning-notes/week-${String(w).padStart(2,"0")}.md`,"Viết 4 mục, mỗi mục 3–5 gạch đầu dòng","Commit + push, điền link note vào bảng Learning notes log ở cuối trang"],
  done:["File note tồn tại trong repo","Có ít nhất 1 điểm 'Còn vướng' (thành thật)","Đã push lên GitHub","Đã điền link vào bảng log"]
});

